module serial2parallel(
	input clk, 
	input rst_n, 
	input din_serial, 
	input din_valid, 
	output [7:0] dout_parallel, 
	output dout_valid
);
// Sequential logic for the circuit
reg [3:0] cnt;
reg [7:0] dout_parallel_reg;
reg dout_valid_reg;
always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		cnt <= 4'd0;
	end
	else begin
		if(din_valid == 1) begin
			dout_parallel_reg[cnt] <= din_serial;
			cnt <= cnt + 1;
			if(cnt == 7) begin
				dout_valid_reg <= 1;
			end
			else begin
				dout_valid_reg <= 0;
			end
		end
	end
end
assign dout_parallel = dout_parallel_reg;
assign dout_valid = dout_valid_reg;
endmodule
